import{_ as i,o as a,c as r,a2 as t}from"./chunks/framework.D3sJ1xc1.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"regulament-pc-check.md","filePath":"regulament-pc-check.md"}'),l={name:"regulament-pc-check.md"};function o(c,e,n,u,s,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h2 id="🖥️-regulament-pc-check-romana" tabindex="-1">🖥️ Regulament PC Check (Română) <a class="header-anchor" href="#🖥️-regulament-pc-check-romana" aria-label="Permalink to &quot;🖥️ Regulament PC Check (Română)&quot;">​</a></h2><hr><h2 id="cap-1-informatii-generale" tabindex="-1">CAP. 1 - INFORMAȚII GENERALE <a class="header-anchor" href="#cap-1-informatii-generale" aria-label="Permalink to &quot;CAP. 1 - INFORMAȚII GENERALE&quot;">​</a></h2><h3 id="_1-1-ce-este-pc-check" tabindex="-1">1.1 Ce este PC Check? <a class="header-anchor" href="#_1-1-ce-este-pc-check" aria-label="Permalink to &quot;1.1 Ce este PC Check?&quot;">​</a></h3><p><strong>PC Check</strong> reprezintă o verificare efectuată de echipa autorizată pentru a confirma că un jucător nu utilizează cheat-uri, bypass-uri sau alte programe care oferă avantaje incorecte în joc.</p><hr><h2 id="cap-2-obligatiile-jucatorului" tabindex="-1">CAP. 2 - OBLIGAȚIILE JUCĂTORULUI <a class="header-anchor" href="#cap-2-obligatiile-jucatorului" aria-label="Permalink to &quot;CAP. 2 - OBLIGAȚIILE JUCĂTORULUI&quot;">​</a></h2><h3 id="_2-1-prezentarea-la-verificare" tabindex="-1">2.1 Prezentarea la verificare <a class="header-anchor" href="#_2-1-prezentarea-la-verificare" aria-label="Permalink to &quot;2.1 Prezentarea la verificare&quot;">​</a></h3><p>În momentul în care un membru al echipei solicită efectuarea unui <strong>PC Check</strong>, jucătorul are obligația de a coopera pe întreaga durată a verificării.</p><h3 id="reguli" tabindex="-1">Reguli <a class="header-anchor" href="#reguli" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este obligatorie prezentarea pe canalul de suport într-un timp rezonabil.</li><li>Nu ai voie să închizi FiveM fără acordul echipei PC Check.</li><li>Nu ai voie să repornești calculatorul fără acordul echipei.</li><li>Nu ai voie să ștergi, modifici sau muți fișiere.</li><li>Nu ai voie să rulezi programe care pot influența verificarea.</li><li>Ești obligat să respecți toate instrucțiunile membrului responsabil de verificare.</li></ul><h3 id="sanctiuni" tabindex="-1">Sancțiuni <a class="header-anchor" href="#sanctiuni" aria-label="Permalink to &quot;Sancțiuni&quot;">​</a></h3><ul><li>Refuzul verificării.</li><li>Refuzul cooperării.</li><li>Tragerea intenționată de timp.</li></ul><p>Aceste abateri pot conduce la <strong>Blacklist Permanent</strong>.</p><hr><h2 id="cap-3-restrictii" tabindex="-1">CAP. 3 - RESTRICȚII <a class="header-anchor" href="#cap-3-restrictii" aria-label="Permalink to &quot;CAP. 3 - RESTRICȚII&quot;">​</a></h2><h3 id="_3-1-software-si-sisteme-neacceptate" tabindex="-1">3.1 Software și sisteme neacceptate <a class="header-anchor" href="#_3-1-software-si-sisteme-neacceptate" aria-label="Permalink to &quot;3.1 Software și sisteme neacceptate&quot;">​</a></h3><p>În timpul verificării nu sunt acceptate configurații sau programe care împiedică desfășurarea corectă a PC Check-ului.</p><h3 id="nu-sunt-acceptate" tabindex="-1">Nu sunt acceptate <a class="header-anchor" href="#nu-sunt-acceptate" aria-label="Permalink to &quot;Nu sunt acceptate&quot;">​</a></h3><ul><li>Sisteme de operare modificate care împiedică verificarea.</li><li>Servicii Windows dezactivate sau imposibil de pornit.</li><li>Cheat-uri.</li><li>Bypass-uri.</li><li>Orice software utilizat pentru obținerea unui avantaj în joc.</li></ul><h3 id="reguli-1" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-1" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Asocierea cu comunități dedicate cheat-urilor sau bypass-urilor poate fi luată în considerare în timpul verificării.</li></ul><hr><h2 id="cap-4-servicii-obligatorii" tabindex="-1">CAP. 4 - SERVICII OBLIGATORII <a class="header-anchor" href="#cap-4-servicii-obligatorii" aria-label="Permalink to &quot;CAP. 4 - SERVICII OBLIGATORII&quot;">​</a></h2><h3 id="_4-1-servicii-windows" tabindex="-1">4.1 Servicii Windows <a class="header-anchor" href="#_4-1-servicii-windows" aria-label="Permalink to &quot;4.1 Servicii Windows&quot;">​</a></h3><p>Următoarele servicii trebuie să fie funcționale în momentul verificării:</p><ul><li>AppInfo</li><li>DPS</li><li>Dnscache</li><li>PcaSvc</li><li>SysMain</li><li>DiagTrack</li><li>EventLog</li><li>BAM</li><li>DusmSvc</li></ul><hr><h3 id="_4-2-restrictii-suplimentare" tabindex="-1">4.2 Restricții suplimentare <a class="header-anchor" href="#_4-2-restrictii-suplimentare" aria-label="Permalink to &quot;4.2 Restricții suplimentare&quot;">​</a></h3><p>Nu sunt acceptate următoarele situații:</p><ul><li>BAM dezactivat.</li><li>ActivitiesCache dezactivat.</li><li>JumpLists dezactivate.</li><li>Thread-uri ale serviciilor oprite.</li></ul><hr><h2 id="cap-5-tentativa-de-bypass" tabindex="-1">CAP. 5 - TENTATIVA DE BYPASS <a class="header-anchor" href="#cap-5-tentativa-de-bypass" aria-label="Permalink to &quot;CAP. 5 - TENTATIVA DE BYPASS&quot;">​</a></h2><h3 id="_5-1-definitie" tabindex="-1">5.1 Definiție <a class="header-anchor" href="#_5-1-definitie" aria-label="Permalink to &quot;5.1 Definiție&quot;">​</a></h3><p>Orice acțiune efectuată cu scopul de a ascunde urmele utilizării programelor interzise este considerată <strong>Tentativă de Bypass</strong>.</p><h3 id="exemple" tabindex="-1">Exemple <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple&quot;">​</a></h3><ul><li>Ștergerea fișierelor.</li><li>Curățarea registrilor (Registry).</li><li>Curățarea Event Logs.</li><li>Curățarea folderului Prefetch.</li><li>Curățarea <code>shell:recent</code>.</li><li>Resetarea serviciilor Windows.</li><li>Modificarea Timestamp-urilor.</li><li>Utilizarea programelor care șterg urme sau string-uri.</li></ul><hr><h3 id="_5-2-programe-monitorizate" tabindex="-1">5.2 Programe monitorizate <a class="header-anchor" href="#_5-2-programe-monitorizate" aria-label="Permalink to &quot;5.2 Programe monitorizate&quot;">​</a></h3><p>Tentativa de Bypass include orice interacțiune înainte de deschiderea FiveM cu următoarele aplicații:</p><ul><li>CMD.</li><li>PowerShell.</li><li>PowerShell ISE.</li><li>Python.</li><li>Registry Editor.</li><li>Process Hacker.</li><li>System Informer.</li></ul><hr><h2 id="cap-6-informatii-suplimentare" tabindex="-1">CAP. 6 - INFORMAȚII SUPLIMENTARE <a class="header-anchor" href="#cap-6-informatii-suplimentare" aria-label="Permalink to &quot;CAP. 6 - INFORMAȚII SUPLIMENTARE&quot;">​</a></h2><h3 id="_6-1-recomandari-si-responsabilitate" tabindex="-1">6.1 Recomandări și responsabilitate <a class="header-anchor" href="#_6-1-recomandari-si-responsabilitate" aria-label="Permalink to &quot;6.1 Recomandări și responsabilitate&quot;">​</a></h3><h3 id="reguli-2" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-2" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Utilizarea programelor de optimizare se face pe propria răspundere.</li><li>Poți deschide un ticket pentru verificarea serviciilor înainte de un eventual PC Check.</li><li>Dacă există un ticket deschis înainte de verificare și acesta nu a fost preluat de Staff, situația va fi analizată separat.</li><li>Echipa <strong>Cheater Team Legacy Of CLT</strong> își rezervă dreptul de a sancționa orice metodă nouă de ascundere a urmelor, chiar dacă aceasta nu este menționată explicit în prezentul regulament.</li></ul><hr><h2 id="cap-7-dispozitii-finale" tabindex="-1">CAP. 7 - DISPOZIȚII FINALE <a class="header-anchor" href="#cap-7-dispozitii-finale" aria-label="Permalink to &quot;CAP. 7 - DISPOZIȚII FINALE&quot;">​</a></h2><h3 id="_7-1-aplicarea-regulamentului" tabindex="-1">7.1 Aplicarea regulamentului <a class="header-anchor" href="#_7-1-aplicarea-regulamentului" aria-label="Permalink to &quot;7.1 Aplicarea regulamentului&quot;">​</a></h3><p>Respectarea prezentului regulament este obligatorie pentru toți jucătorii serverului.</p><h3 id="reguli-3" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-3" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Refuzul cooperării poate conduce la sancțiuni severe.</li><li>Orice metodă de evitare a verificării poate fi sancționată.</li><li>Echipa PC Check are dreptul de a interpreta fiecare situație în funcție de dovezile existente.</li><li>Regulamentul poate fi modificat ori de câte ori este necesar.</li></ul><hr><h2 id="📌-nota" tabindex="-1">📌 NOTĂ <a class="header-anchor" href="#📌-nota" aria-label="Permalink to &quot;📌 NOTĂ&quot;">​</a></h2><p>Scopul prezentului regulament este menținerea unui mediu <strong>fair-play</strong>, fără programe interzise sau metode de fraudare.</p><p>Respectarea tuturor prevederilor este obligatorie pentru fiecare jucător al comunității <strong>Legacy Of CLT Roleplay</strong>.</p>',56)])])}const m=i(l,[["render",o]]);export{p as __pageData,m as default};
